// Builds src/data/stories.generated.ts from the app's own series files, so
// the website and the app can never drift apart.
//
//   npm run gen:stories
//
// Reads ../lib/models/series/*.dart (themselves generated by
// tools/gen_series.dart) and keeps what a web page needs: the series, its
// episodes, their length, and where a free preview stops.

import { readFileSync, writeFileSync, readdirSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const seriesDir = join(here, '..', '..', 'lib', 'models', 'series');
const outFile = join(here, '..', 'src', 'data', 'stories.generated.ts');

/** `'Rashid\'s Salam'` -> `Rashid's Salam` */
const unquote = (s) => s.replace(/\\(['"$])/g, '$1');

function field(block, name) {
  const m = block.match(
    new RegExp(`${name}:\\s*'((?:[^'\\\\]|\\\\.)*)'`, 's'),
  );
  return m ? unquote(m[1]) : null;
}

/** Splits the `episodes: [...]` list into one text block per Story(...). */
function episodeBlocks(src) {
  const start = src.indexOf('episodes: [');
  if (start < 0) return [];
  return src
    .slice(start)
    .split(/\n {4}Story\(/)
    .slice(1);
}

function parseSeries(file) {
  const src = readFileSync(join(seriesDir, file), 'utf8');
  const header = src.slice(0, src.indexOf('episodes: ['));

  const episodes = episodeBlocks(src).map((block, i) => {
    const lines = [
      ...block.matchAll(
        /start: Duration\(milliseconds: (\d+)\),\s*end: Duration\(milliseconds: (\d+)\),\s*text: '((?:[^'\\]|\\.)*)'/gs,
      ),
    ].map((m) => ({
      startMs: Number(m[1]),
      endMs: Number(m[2]),
      text: unquote(m[3]),
    }));
    const ends = lines.map((l) => l.endMs);
    const durationMs = ends.length ? ends[ends.length - 1] : 0;
    // The same rule the app uses: a free listener hears episode one up to
    // the end of the caption line that crosses the halfway point.
    const half = Math.floor(durationMs / 2);
    const previewEndMs = i === 0
      ? (ends.find((e) => e >= half) ?? half)
      : null;
    const audioAsset = field(block, 'audioAsset') ?? '';

    return {
      id: field(block, 'id'),
      title: field(block, 'title'),
      audioKey: audioAsset.replace(/^assets\/audio\//, ''),
      durationMs,
      previewEndMs,
      // The read-along text, kept only for the part the website may play.
      captions:
        previewEndMs == null
          ? []
          : lines.filter((l) => l.endMs <= previewEndMs),
    };
  });

  return {
    id: field(header, 'id'),
    title: field(header, 'title'),
    description: field(header, 'description'),
    language: header.includes('StoryLanguage.urdu') ? 'urdu' : 'english',
    category: header.includes('StoryCategory.prophets') ? 'prophets' : 'moral',
    // assets/covers/respect.webp -> respect
    cover: (field(header, 'coverAsset') ?? '').replace(
      /^assets\/covers\/(.+)\.webp$/,
      '$1',
    ),
    episodes,
  };
}

const all = readdirSync(seriesDir)
  .filter((f) => f.endsWith('.dart'))
  .map(parseSeries)
  // English first, then Urdu; Prophets before moral series, as in the app.
  .sort((a, b) =>
    a.language === b.language
      ? a.category === b.category
        ? 0
        : a.category === 'prophets'
          ? -1
          : 1
      : a.language === 'english'
        ? -1
        : 1,
  );

const banner = `// GENERATED by scripts/gen-stories.mjs from the app's series files.
// Do not edit by hand: run \`npm run gen:stories\` instead.

import type { Series } from '@/data/types';

export const allSeries: Series[] = `;

mkdirSync(dirname(outFile), { recursive: true });
writeFileSync(outFile, banner + JSON.stringify(all, null, 2) + ';\n');

const episodes = all.reduce((n, s) => n + s.episodes.length, 0);
console.log(`wrote ${all.length} series, ${episodes} episodes`);
